import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums: single items ---
  it.todo("should charge 5 G for an empty item list — only the processing fee");
  it.todo("should quote a plain sword — 100 G base + 10 G first insurance + 5 G fee = 115 G");
  it.todo("should quote a plain amulet — 60 G base + 6 G first insurance + 5 G fee = 71 G");
  it.todo("should quote a plain staff — 80 G base + 8 G first insurance + 5 G fee = 93 G");
  it.todo("should quote a plain potion — 40 G base + 4 G first insurance + 5 G fee = 45 G");
  it.todo("should quote a single rune — 25 G base + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");

  // --- Building block of 3 alike components ---
  it.todo("should quote 2 runes — 50 G base premium (no block)");
  it.todo("should quote 3 runes — 60 G base premium (block applies)");
  it.todo("should quote 4 runes — 100 G base premium (no block: block requires exactly 3)");
  it.todo("should quote 7 runes — 175 G base premium");

  // --- "Alike" means exactly the same type ---
  it.todo("should quote 2 runes + 1 moonstone — 75 G base premium (no block: different types)");
  it.todo("should quote 3 runes + 3 moonstones — 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("should add a 50% curse surcharge — cursed sword base 100 G + 50 G curse");
  it.todo("should add a 30% high-enchantment surcharge at exactly enchantment 5 — sword base 100 G + 30 G");
  it.todo("should not add a high-enchantment surcharge at enchantment 4 — sword base 100 G only");
  it.todo("should apply both surcharges to a cursed sword with enchantment 5 — 100 G + 50 G + 30 G");

  // --- Policy-wide modifiers ---
  it.todo("should apply a 20% loyalty discount at exactly 2 years with MHPCO");
  it.todo("should not apply a loyalty discount at 1 year with MHPCO");
  it.todo("should apply a 10% first insurance surcharge to every item in a quote");
  it.todo("should apply a 15% follow-up discount on the customer's second contract");

  // --- Modifier scope on multi-item policies ---
  it.todo("should apply the curse surcharge only to the cursed item — cursed sword + plain amulet: base 160 G + 50 G curse = 210 G before further modifiers and fee");

  // --- Rounding in MHPCO's favour ---
  it.todo("should round a premium of 197.5 G up to 198 G");
  it.todo("should round a payout of 350.5 G down to 350 G");

  // --- Integration examples ---
  it.todo("should quote a newcomer's cursed sword (0 years, steel, enchantment 3) — premium 165 G");
  it.todo("should quote a long-standing customer's second contract (3 years, cursed sword, enchantment 7) — premium 160 G");

  // --- Claims: standard reimbursement ---
  it.todo("should pay out 400 G for a regular sword (steel, enchantment 3) with 500 G damage — full reimbursement minus 100 G deductible");
  it.todo("should pay out 100 G for a rune (no enchantment, no material) with 200 G damage — no special clause applies");

  // --- Claims: special clauses ---
  it.todo("should pay out 400 G for a steel sword, enchantment 9, damage 1000 G — 50% clause then deductible");
  it.todo("should pay out 700 G for a dragon-material sword, enchantment 5, damage 800 G — full reimbursement then deductible");
  it.todo("should pay out 400 G for a dragon-material sword, enchantment 9, damage 1000 G — the 50% rule wins, then deductible");
  it.todo("should pay out 400 G for a dragon-material sword at exactly enchantment 8, damage 1000 G — 50% clause then deductible");

  // --- Claims: deductible per damage event ---
  it.todo("should apply the 100 G deductible once per damaged item — sword 500 G + amulet 300 G = 600 G payout");

  // --- Claims: insurance sum and cap ---
  it.todo("should report the remaining cap after a claim — sword policy (cap 2000 G), damage 500 G leaves 1600 G");
  it.todo("should base the cap on the unmodified insurance value — cursed sword premium 165 G but cap 2000 G");
  it.todo("should cap a policy covering a sword and an amulet at 3200 G (insurance sum 1600 G)");
  it.todo("should exclude the block discount from the insurance sum — sword + 3 runes: insurance sum 1750 G, cap 3500 G");

  // --- Claims: cap exhaustion across successive claims ---
  it.todo("should pay out 1400 G and leave 600 G cap for a first 1500 G claim on a sword policy");
  it.todo("should reduce a second 1500 G claim to the remaining 600 G cap, leaving 0 G");

  // --- Multiple items of the same type ---
  it.todo("should insure two swords — insurance sum 2000 G, cap 4000 G");
  it.todo("should treat two sword damage entries as separate damages, each with its own deductible");

  // --- Error handling ---
  it.todo("should reject a quote containing an unknown item type (broomstick)");
  it.todo("should reject a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured)");
  it.todo("should reject a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured)");
  it.todo("should reject a claim containing a damage entry with a negative amount (-200)");

  // --- Multi-step scenarios ---
  it.todo("should process steps sequentially and return results in the same order and length as the input steps");
  it.todo("should resolve a claim's policy reference by the zero-based index of the quote step that created it");
});
EOF
echo "--- written ---" && pnpm test:unit:basic 2>&1 | tail -20

