import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums: single items ---
  it("should charge 5 G for an empty item list — only the processing fee", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
  });
  it.todo("should quote a plain sword — 100 G base + 10 G first insurance + 5 G fee = 115 G");
  it.todo("should quote a plain amulet — 60 G base + 6 G first insurance + 5 G fee = 71 G");
claim-office.spec.ts

