python3 - <<'PY'
p = "src/claim-office.ts"
s = open(p).read()

old = """const FIRST_INSURANCE_PERCENT = 10;
const CURSE_PERCENT = 50;"""
new = """const FIRST_INSURANCE_PERCENT = 10;
const CURSE_PERCENT = 50;
const HIGH_ENCHANTMENT_PERCENT = 30;
const HIGH_ENCHANTMENT_THRESHOLD = 5;"""
assert old in s
s = s.replace(old, new, 1)

old_type = "type Item = { type: string; cursed?: boolean };"
new_type = "type Item = { type: string; cursed?: boolean; enchantment?: number };"
assert old_type in s
s = s.replace(old_type, new_type, 1)

old_sur = """// Item-specific modifiers apply to the base premium of the affected item,
// so they are computed per item rather than from the grouped totals.
const itemSurcharges = (items: Item[]): number =>
  items.reduce(
    (total, item) =>
      total + (item.cursed ? percentOf(BASE_PREMIUMS[item.type], CURSE_PERCENT) : 0),
    0,
  );"""
new_sur = """// Components carry no enchantment level at all, so a missing value is
// simply not highly enchanted.
const isHighlyEnchanted = (item: Item): boolean =>
  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;

// Item-specific modifiers apply to the base premium of the affected item,
// so they are computed per item rather than from the grouped totals. A
// cursed, highly enchanted item takes both surcharges.
const itemSurcharge = (item: Item): number => {
  const basePremium = BASE_PREMIUMS[item.type];
  const curse = item.cursed ? percentOf(basePremium, CURSE_PERCENT) : 0;
  const enchantment = isHighlyEnchanted(item)
    ? percentOf(basePremium, HIGH_ENCHANTMENT_PERCENT)
    : 0;

  return curse + enchantment;
};

const itemSurcharges = (items: Item[]): number =>
  items.reduce((total, item) => total + itemSurcharge(item), 0);"""
assert old_sur in s
open(p, "w").write(s.replace(old_sur, new_sur, 1))
PY
