  const PROCESSING_FEE = 5;
  const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;

  const FIRST_INSURANCE_PERCENT = 10;
  const FOLLOW_UP_PERCENT = 15;
  const LOYALTY_PERCENT = 20;
  const LOYALTY_THRESHOLD_YEARS = 2;
  const CURSE_PERCENT = 50;
  const HIGH_ENCHANTMENT_PERCENT = 30;
  const HIGH_ENCHANTMENT_THRESHOLD = 5;

  const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40 };
  const COMPONENT_BASE_PREMIUM = 25;
  const COMPONENT_TYPES = ["rune", "moonstone"];
  const BLOCK_SIZE = 3;
  const BLOCK_BASE_PREMIUM = 60;

  const BASE_PREMIUMS: Record<string, number> = {
    ...MAIN_ITEM_BASE_PREMIUMS,
    ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
  };

  type Item = { type: string; cursed?: boolean; enchantment?: number };
  type Step = { items: Item[] };
  type Customer = { yearsWithMHPCO: number };
  type Scenario = { customer: Customer; steps: Step[] };

  const countByType = (items: Item[]): Map<string, number> =>
    items.reduce((counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1), new Map<string, number>());

  const basePremiumForType = (type: string, count: number): number =>
    count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

  const stepBasePremium = (step: Step): number =>
    [...countByType(step.items)].reduce((total, [type, count]) => total + basePremiumForType(type, count), 0);

  const isHighlyEnchanted = (item: Item): boolean =>
    item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;

  const itemSurcharge = (item: Item): number => {
    const basePremium = BASE_PREMIUMS[item.type];
    const curseSurcharge = item.cursed ? percentOf(basePremium, CURSE_PERCENT) : 0;
    const enchantmentSurcharge = isHighlyEnchanted(item) ? percentOf(basePremium, HIGH_ENCHANTMENT_PERCENT) : 0;
    return curseSurcharge + enchantmentSurcharge;
  };

  const totalItemSurcharges = (items: Item[]): number =>
    items.reduce((total, item) => total + itemSurcharge(item), 0);

  const isLongStanding = (customer: Customer): boolean =>
    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

  const netPolicyModifier = (basePremium: number, customer: Customer, isFollowUpContract: boolean): number => {
    const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
    const loyaltyDiscount = isLongStanding(customer) ? percentOf(basePremium, LOYALTY_PERCENT) : 0;
    const followUpDiscount = isFollowUpContract ? percentOf(basePremium, FOLLOW_UP_PERCENT) : 0;
    return firstInsurance - loyaltyDiscount - followUpDiscount;
  };

  // Rounded in the MHPCO's favour: premiums round up.
  const quotePremium = (step: Step, customer: Customer, isFollowUpContract: boolean): number => {
    const basePremium = stepBasePremium(step);
    return Math.ceil(
      basePremium + totalItemSurcharges(step.items) + netPolicyModifier(basePremium, customer, isFollowUpContract) + PROCESSING_FEE,
    );
  };

  export const runScenario = (scenario: unknown): { results: unknown[] } => {
    const { customer, steps } = scenario as Scenario;
    // Every contract after the customer's first is a follow-up.
    const results = steps.map((step, index) => ({ premium: quotePremium(step, customer, index > 0) }));
    return { results };
  };

Implement the MINIMAL production code to make ALL TWENTY-THREE active tests pass:
- Model the two step kinds. Suggested: `type QuoteStep = { op: "quote"; items: Item[] }`, `type ClaimStep = { op: "claim"; policy: number; incident: Incident }`, `type Step = QuoteStep | ClaimStep`, with `Incident = { cause: string; damages: Damage[] }` and `Damage = { itemType: string; amount: number }`. Discriminate on `step.op`.
- IMPORTANT — the existing 22 tests: their quote steps DO carry `op: "quote"`, so discriminating on `op` is safe. Verify this holds.
- Add INSURANCE_VALUES (sword 1000, and the rest of the price list at your discretion).
- For a claim: resolve `step.policy` to the quote step at that index, compute the payout for each damage entry (full damage amount minus the 100 G deductible for now — NO special clauses yet), sum them, and report `{ payout, remainingCap }`.
- The cap is 2 * (sum of insurance values of the policy's items). Track how much of each policy's cap has been consumed so a later test can exhaust it — but keep this as simple as the single active claim test allows.
- Rounding: the spec says payouts round DOWN (Math.floor), in the MHPCO's favour. The current test has no fractional payout so it does not force this, but the direction is spec'd and the payout-rounding test is deferred and pending. Use your judgement — if you add Math.floor, say so and note that no active test forces it yet.

Do NOT implement: the >= 8 enchantment 50% clause, the dragon-material full-reimbursement clause, cap exhaustion across multiple claims beyond what is needed here, error handling/validation (unknown item types, uninsured damaged items, over-count damages, negative amounts), or a quote-counter to fix the known `index > 0` follow-up limitation. None is forced by an active test yet.

KNOWN LIMITATION to preserve: `index > 0` currently treats any step after the first as a follow-up contract. With claim steps now existing, this is WRONG in principle (the spec counts quotes, not steps) — but note that in THIS test the claim is step 1 and is not a quote, so nothing observable breaks yet. Do NOT fix it now; a later test will force it. Mention it in your report.

Keep `percentOf` and its exact-integer-percent arithmetic and all explanatory comments. Verify all twenty-three active tests pass with `pnpm test:unit:basic`.

